#!/usr/bin/env python3
import json,sys
from pathlib import Path
s=json.loads("\"highlightEnabled,\\n+      commentaryEnabled: options?.commentaryEnabled,\\n     };\\n     vscode.postMessage({\\n       type: 'RUN_AS_SLASH_COMMAND',\\ndiff --git a/src/webview/src/stores/commentary-store.ts b/src/webview/src/stores/commentary-store.ts\\nnew file mode 100644\\nindex 0000000..5d9c44f\\n--- /dev/null\\n+++ b/src/webview/src/stores/commentary-store.ts\\n@@ -0,0 +1,13 @@\\n+import { create } from 'zustand';\\n+\\n+interface CommentaryState {\\n+  messages: { text: string; sessionId: string; timestamp: number }[];\\n+  add: (text: string, sessionId: string) => void;\\n+  clear: () => void;\\n+}\\n+\\n+export const useCommentaryStore = create<CommentaryState>(set => ({\\n+  messages: [],\\n+  add: (text, sessionId) => set(state => ({ messages: [...state.messages, { text, sessionId, timestamp: Date.now() }] })),\\n+  clear: () => set({ messages: [] }),\\n+}));\\ndiff --git a/src/webview/src/stores/workflow-store.ts b/src/webview/src/stores/workflow-store.ts\\nindex e7b6f02..87a8dfb 100644\\n--- a/src/webview/src/stores/workflow-store.ts\\n+++ b/src/webview/src/stores/workflow-store.ts\\n@@ -53,6 +53,8 @@ interface MainWorkflowSnapshot {\\n }\\n \\n interface WorkflowStore {\\n+  commentaryEnabled: boolean;\\n+  setCommentaryEnabled: (enabled: boolean) => void;\\n   // State\\n   nodes: Node[];\\n   edges: Edge[];\\n@@ -297,6 +299,8 @@ export function createWorkflowFromCanvas(nodes: Node[], edges: Edge[]): Workflow\\n }\\n \\n export const useWorkflowStore = create<WorkflowStore>((set, get) => ({\\n+  commentaryEnabled: false,\\n+  setCommentaryEnabled: enabled => set({ commentaryEnabled: enabled }),\\n   // Initial State - デフォルトでStartノードとEndノードを含む\\n   nodes: [DEFAULT_START_NODE, DEFAULT_END_NODE],\\n   edges: [],\\n\"")
p=Path(sys.argv[1]); p.parent.mkdir(parents=True,exist_ok=True)
with p.open('ab') as f: f.write(s.encode('utf-8'))
